contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address admin, bool access) public payable {
        require(admin != address(this));
        bool before = c.isAdmin(admin);
        bool reverted;
        try c.adjustAdminAccess(admin, access) { reverted = false; } catch { reverted = true; }
        bool after = c.isAdmin(admin);
        assert(reverted && after == before);
    }
    receive() external payable {}
}

